.cl-scope {
  --cl-on-ink: #FFFFFF;              /* 진한 배경(보라 · 먹색 · 빨강) 위 글자 */
  --cl-primary-fill: var(--cl-primary);        /* 주 버튼 배경 · 포커스 · 그래프 막대 */
  --cl-primary-text: var(--cl-primary-pressed);        /* 링크 · 현재 메뉴 · 연보라 위 글자 (흰 배경 6.47:1) */
  --cl-primary-tint-hover: #EADDFB;
  --cl-danger-pressed: #A8191A;
  --cl-row-hover: #FAFAFB;
  --cl-track: #ECECEF;
  --cl-nav-hover: #EFEFF1;
  --cl-scrim: rgba(0, 0, 0, .4);
}
.cl-btn--primary, .cl-btn--danger, .cl-chip[aria-pressed="true"],
.cl-pagination__page.is-current, .cl-toast, .cl-selbar, .cl-selbar__btn, .cl-selbar__close,
.cl-avatar, .cl-ws-brand__mark { color: var(--cl-on-ink); }
.cl-btn--danger:hover { background: var(--cl-danger-pressed); }
.cl-btn--tint:hover, .cl-ws-term:hover { background: var(--cl-primary-tint-hover); }
.cl-table tbody tr:hover { background: var(--cl-row-hover); }
.cl-ws-nav__item:hover, .cl-ws-rail__item:hover { background: var(--cl-nav-hover); }
.cl-pd-mini, .cl-pd-bar, .cl-ta-meter { background: var(--cl-track); }
.cl-dialog::backdrop { background: var(--cl-scrim); }

.cl-scope {
  --cl-on-ink-2: #E5E5EA;       /* 진한 바탕 위 둘째 글자 — 이어보기 강의 이름 (#1D1D1F 위 15.1:1) */
  --cl-on-ink-muted: #C7C7CC;   /* 진한 바탕 위 보조 글자 — 이어보기 머리 줄 (#1D1D1F 위 11.4:1) */
}
.cl-hero { border-radius: var(--cl-radius-lg); color: var(--cl-on-ink); }
.cl-hero__eyebrow { color: var(--cl-on-ink-muted); }
.cl-hero__title { color: var(--cl-on-ink); }
.cl-hero__lecture { color: var(--cl-on-ink-2); }
.cl-teacher-card__name { font-size: var(--cl-fs-section-title); }

.cl-scope { --cl-media-bg: #F4F4F6; }   /* 올린 이미지 칸 바탕. 다크에서도 뒤집지 않는다 */
.cl-row__thumb, .cl-card-item__thumb, .cl-ws-brand__logo, img.cl-teacher-card__photo { background: var(--cl-media-bg); }
html[data-theme="dark"] .cl-scope :is(.cl-row__thumb, .cl-card-item__thumb) { box-shadow: 0 0 0 1px var(--cl-hairline); }

/* 크기는 토큰이 들고, 화면은 읽기만 한다 */
.cl-scope { --cl-fs-hero: clamp(40px, 5.6vw, 80px); }
.cl-home-hero__title { font-size: var(--cl-fs-hero); }

/* 6px 을 척도에 등록한다 (배지 · 메뉴 항목 · 보기 전환 · 작은 버튼도 쓰는 값) */
.cl-scope { --cl-radius-2xs: 6px; }
/* 작은 썸네일만 6px */
.cl-home-course__thumb { border-radius: var(--cl-radius-2xs); }
/* 나머지 네모 면은 8px — 16px 을 쓰던 7곳 포함 */
.cl-home-cat,
.cl-home-teacher,
.cl-home-teacher__photo,
.cl-home-hero__media,
.cl-home-gallery img,
.cl-home-gallery > *,
.cl-home-banner,
.cl-home-slider__viewport,
.cl-home-split__fallback,
.cl-home-tile { border-radius: var(--cl-radius-sm); }
/* 모바일에서 썸네일이 가로 전체가 되면 8px (지금은 12px) */
@media (max-width: 900px) { .cl-home-course__thumb { border-radius: var(--cl-radius-sm); } }

/* 줄 hover 값을 하나로 — 공개 #FAF7FE · 전체강좌 #FAFAFC · 작업공간 #FAFAFB 세 값이 쓰이고 있었다 */
.cl-scope { --cl-row-hover: #FAF7FE; }
.cl-home-course:hover,
.cl-qna-item:hover,
.cl-post-row:not(.cl-post-row--head):hover,
.cl-teacher__course:hover,
.cl-cs-row:hover,
.cl-auth__method:hover { background: var(--cl-row-hover); }
/* 공통층 전환 목록에 border-color 가 빠져 있어 카드 테두리만 뚝 바뀌었다 */
.cl-scope :is(button, a) { transition: background var(--cl-dur) var(--cl-ease), color var(--cl-dur) var(--cl-ease), border-color var(--cl-dur) var(--cl-ease), transform var(--cl-dur) var(--cl-ease); }
/* 카드도 줄처럼 제목이 보라로 — 분류 카드만 빠져 있었다 */
.cl-home-cat:hover .cl-home-cat__head strong { color: var(--cl-primary-pressed); }

/* 공개 화면도 작업공간과 같은 가독성 단계로 — 작업공간만 14 · 13 으로 올라가 있었다 */
.cl-scope.cl-pub-body { --cl-fs-ui: 14px; --cl-fs-caption: 13px; --cl-fs-table-head: 13px; --cl-fs-body-sm-pub: 15px; --cl-fs-section-pub: clamp(26px, 2.2vw, 32px); }
/* 머리 — 제목은 한 단계 내리고, 부제는 한 단계 올린다 */
.cl-cs-title { font-size: var(--cl-fs-display); letter-spacing: -0.03em; }
.cl-cs-sub { font-size: var(--cl-fs-body-sm-pub); }
.cl-cs-crumb { font-size: var(--cl-fs-caption); }
/* 왼쪽 필터 */
.cl-cs-filter__title { font-size: var(--cl-fs-caption); font-weight: 400; color: var(--cl-ink-muted); }
.cl-cs-cate, .cl-cs-subject, .cl-cs-cate.is-child { font-size: var(--cl-fs-body-sm-pub); }
.cl-cs-cate__count { font-size: var(--cl-fs-caption); }
.cl-cs-search input { font-size: var(--cl-fs-ui); }
/* 목록 위 줄 */
.cl-cs-count, .cl-cs-sort { font-size: var(--cl-fs-ui); }
/* 카드 */
.cl-cs-meta, .cl-cs-teacher, .cl-cs-stats { font-size: var(--cl-fs-caption); }
.cl-cs-name { font-size: var(--cl-fs-body-public); }
.cl-cs-more { font-size: var(--cl-fs-ui); }
.cl-cs-row__text .cl-cs-meta, .cl-cs-row__stats-mobile { font-size: var(--cl-fs-caption); }
@media (max-width: 900px) { .cl-cs-count, .cl-cs-sort { font-size: var(--cl-fs-caption); } }

.cl-ws-nav__label { width: 100%; height: 34px; border: 0; background: transparent; font: inherit; font-size: var(--cl-fs-15); font-weight: 600; color: var(--cl-ink-2); justify-content: space-between; border-radius: var(--cl-radius-2xs); cursor: pointer; text-align: left; transition: background var(--cl-dur) var(--cl-ease), color var(--cl-dur) var(--cl-ease); }
.cl-ws-nav__label:hover { background: var(--cl-nav-hover); color: var(--cl-ink); }
.cl-ws-nav__label .cl-icon { color: var(--cl-ink-muted); transition: transform 220ms cubic-bezier(.2, .8, .2, 1); }
.cl-ws-nav__label[aria-expanded="false"] .cl-icon { transform: rotate(-90deg); }
.cl-ws-nav__items { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 220ms cubic-bezier(.2, .8, .2, 1), opacity 180ms ease-out; }
.cl-ws-nav__items.is-closed { grid-template-rows: 0fr; opacity: 0; }
.cl-ws-nav__items-inner { min-height: 0; overflow: hidden; display: flex; flex-direction: column; gap: 5px; padding-top: 5px; }
.cl-ws-nav__items:not(.is-closed) .cl-ws-nav__item { animation: cl-nav-in 220ms ease-out both; }
@keyframes cl-nav-in { from { transform: translateY(-4px); } to { transform: none; } }
@media (prefers-reduced-motion: reduce) { .cl-ws-nav__items, .cl-ws-nav__label .cl-icon { transition: none; } .cl-ws-nav__item { animation: none !important; } }

