.cl-ws-nav__item { font-size: var(--cl-fs-15); }
.cl-ws-nav__group { gap: 0; } /* 접힌 묶음에 빈 틈이 남지 않게 — 이름과 메뉴 사이 5px 은 안쪽 여백으로 */
