/* 헤더를 공개 화면 글자 단계에 맞춘다 — 로고 17px 과 같은 키 */
.cl-pub-nav__item { font-size: var(--cl-fs-body-public); }
.cl-pub-nav { gap: 40px; }
@media (max-width: 1100px) { .cl-pub-nav { gap: 24px; } }

/* 로고는 세로 기준으로 키우고 비율은 건드리지 않는다 (정사각형 · 가로형 둘 다) */
.cl-pub-brand__logo { height: 40px; width: auto; max-width: 240px; object-fit: contain; }
.cl-pub-brand--logo-only .cl-pub-brand__logo { height: 50px; }
@media (max-width: 900px) {
  .cl-pub-brand__logo, .cl-pub-brand--logo-only .cl-pub-brand__logo { height: 36px; max-width: 160px; }
}

/* 태블릿에서는 로고가 있으면 학원 이름 글자를 접는다 — 메뉴가 들어갈 자리를 만든다 */
@media (max-width: 1100px) {
  .cl-pub-brand:has(.cl-pub-brand__logo) .cl-pub-brand__name { display: none; }
}

/* 내용이 짧아도 꼬리말은 화면 맨 아래에 — 몸통을 세로 flex 로, 본문이 남은 높이를 채운다 */
.cl-pub-body { min-height: 100vh; min-height: 100dvh; display: flex; flex-direction: column; }
.cl-pub-main { flex: 1 0 auto; }
.cl-pub-footer { flex: none; }

