var m = btn && btn.closest('.cl-popover').querySelector('.cl-popover__panel.cl-menu');
if (m && !m.querySelector('.cl-menu__sep')) {
  var mk = function () { var d = doc.createElement('div'); d.className = 'cl-menu__sep'; return d; };
  var at = function (name) {
    return [].slice.call(m.querySelectorAll('.cl-menu__item')).filter(function (el) {
      return el.textContent.trim() === name;
    })[0];
  };
  // 계정 묶음이 시작되는 자리
  var acct = at('학원 탈퇴') || at('로그아웃');
  // 도움 묶음은 계정 바로 위로 모은다 — 선생님 작업공간에서는 [나의 QR코드] 사이에 끼어 있었다
  var help = ['이용 매뉴얼', '고객센터'].map(at).filter(Boolean);
  if (acct) help.forEach(function (el) { acct.before(el); });
  if (help[0]) help[0].before(mk());
  if (acct) acct.before(mk());
  var head = m.querySelector('.cl-menu__head');
  if (head) head.after(mk());
  var quit = at('학원 탈퇴');
  if (quit) quit.classList.add('cl-menu__item--danger');
}

