confirmed.css:
/* 공개 화면 글자 단계에 두 단계를 등록한다 (cl-tokens.css 로 올라갈 값) */
.cl-scope {
  --cl-fs-section-pub: clamp(26px, 2.2vw, 32px);  /* 섹션 제목 — 대표 강좌 · 선생님 소개 등 6곳 */
}
/* 설명이 강좌 이름보다 크지 않게 — 제목 32 · 강좌 19 · 설명 17 */
.cl-home-head__title { font-size: var(--cl-fs-section-pub); }
.cl-home-head__sub { font-size: var(--cl-fs-body-public); }

/* 2열로 깔리는 넓은 화면. 글을 선 끝에서 8px 들이고, hover 바탕은 선 폭 안에서만 깔린다 */
@media (min-width: 901px) {
  .cl-home[data-preset="default"] .cl-home-course { padding: var(--cl-space-4) var(--cl-space-2); }
}

/* 900px 이하: 가로 꽉 찬 카드 대신 [썸네일 | 글] 한 줄로 */
@media (max-width: 900px) {
  .cl-home[data-preset="default"] .cl-home-courses { display: grid; grid-template-columns: minmax(0, 1fr); column-gap: var(--cl-space-5); border-top: 1px solid var(--cl-ink); }
  .cl-home[data-preset="default"] .cl-home-course {
    grid-template-columns: 112px minmax(0, 1fr) auto;
    grid-template-areas: "thumb body body" "thumb teacher std";
    column-gap: var(--cl-space-3); row-gap: 2px;
    align-items: start;
    padding: var(--cl-space-3) var(--cl-space-2);
    height: 100%; box-sizing: border-box;
  }
  .cl-home[data-preset="default"] .cl-home-course__num,
  .cl-home[data-preset="default"] .cl-home-course__go { display: none; }
  .cl-home[data-preset="default"] .cl-home-course__thumb { grid-area: thumb; border-radius: var(--cl-radius-2xs, var(--cl-radius-2xs)); }
  .cl-home[data-preset="default"] .cl-home-course__thumb .cl-thumb-text { font-size: var(--cl-fs-caption); padding: 8px 10px; }
  .cl-home[data-preset="default"] .cl-home-course__body { grid-area: body; }
  .cl-home[data-preset="default"] .cl-home-course__title { font-size: var(--cl-fs-lead); }
  .cl-home[data-preset="default"] .cl-home-course__teacher { grid-area: teacher; display: block; align-self: end; }
  .cl-home[data-preset="default"] .cl-home-course__std { grid-area: std; display: block; align-self: end; }
}
/* 601~900px: 두 칸씩 */
@media (min-width: 601px) and (max-width: 900px) {
  .cl-home[data-preset="default"] .cl-home-courses { grid-template-columns: repeat(2, minmax(0, 1fr)); border-top: 0; }
  .cl-home[data-preset="default"] .cl-home-courses > li:nth-child(-n + 2) .cl-home-course { border-top: 1px solid var(--cl-ink); }
}
/* 600px 이하: 썸네일을 한 번 더 줄인다 */
@media (max-width: 600px) {
  .cl-home[data-preset="default"] .cl-home-course { grid-template-columns: 96px minmax(0, 1fr) auto; }
}

/* 빈 자리는 연보라를 한 단계 밝혀 거의 흰색으로 — 보라 덩어리로 읽히지 않게 */
.cl-home-teacher__photo { background: var(--cl-primary-wash); }
.cl-home-hero__media:not(:has(img)),
.cl-home-banner:not(:has(img)) { background-color: var(--cl-primary-wash); }

/* 첫 칸만 보라로 칠하고 두 줄을 먹던 특별 대우를 없앤다 */
.cl-home[data-preset="default"] .cl-home-cat:first-child {
  background: var(--cl-canvas); border-color: var(--cl-hairline); color: var(--cl-ink);
}
.cl-home[data-preset="default"] .cl-home-cat:first-child .cl-home-cat__subs { color: var(--cl-ink-2); }
.cl-home[data-preset="default"] .cl-home-cat:first-child small.cl-num { color: var(--cl-ink-muted); }
.cl-home[data-preset="default"] .cl-home-cat:first-child .cl-home-cat__go { color: var(--cl-primary-pressed); }
/* 위 규칙이 hover 보다 우선순위가 높아 테두리를 덮는다 — 같은 무게로 되돌려 준다 */
.cl-home[data-preset="default"] .cl-home-cat:first-child:hover { border-color: var(--cl-primary); }
@media (min-width: 901px) {
  /* 칸 수를 고정하지 않는다 — 폭에 맞춰 알아서 정해진다 */
  .cl-home[data-preset="default"] .cl-home-cats { grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); }
  .cl-home[data-preset="default"] .cl-home-cat:first-child:nth-last-child(n + 3) { grid-row: auto; }
  /* 1~3개는 격자를 내용만큼만 넓혀 카드가 늘어나 보이지 않게 */
  .cl-home[data-preset="default"] .cl-home-cats:has(> :nth-child(3):last-child) { max-width: 940px; }
  .cl-home[data-preset="default"] .cl-home-cats:has(> :nth-child(2):last-child) { max-width: 620px; }
  .cl-home[data-preset="default"] .cl-home-cats:has(> :only-child) { max-width: 300px; }
}
/* 고를 게 하나뿐이면 "분류별로 찾기" 가 성립하지 않는다 — 0개일 때 숨기는 규칙을 한 칸 넓힌다 */
.cl-home[data-preset="default"] .cl-home-sec:has(.cl-home-cats > :only-child) { display: none; }

/* 분류가 많아도 메인이 길어지지 않게 여섯 개까지만 */
.cl-home-cats > :nth-child(n + 7) { display: none; }
/* [분류 더보기] — 둘째 줄에서 20px 아래, 가운데. 버튼은 공통 cl-btn--float + 화살표 cl-btn__arrow */
.cl-home-cats-more { display: flex; justify-content: center; margin-top: 20px; }
.cl-home-cats-more > .cl-btn { height: var(--cl-h-control-lg); padding: 0 20px; font-size: var(--cl-fs-body-public); }

