confirmed.css:
/* 분류 카드 — 마우스를 올리면 아이콘이 아래에서 올라오고 [강좌 보기]가 오른쪽으로 */
.cl-home-cat { position: relative; }
.cl-home-cat__deco {
  position: absolute; right: var(--cl-space-4); bottom: var(--cl-space-3);
  width: 36px; height: 36px;
  color: var(--cl-heat-1);
  opacity: .45; transform: translateY(0);
  transition: opacity 150ms ease-out, transform 150ms ease-out;
  pointer-events: none;
}
.cl-home-cat__go { transition: transform 150ms ease-out, color 150ms ease-out; }
.cl-home-cat:hover .cl-home-cat__deco { opacity: 1; transform: translateY(-4px); }
.cl-home-cat:hover .cl-home-cat__go { transform: translateX(10px); }
/* 움직임 줄이기를 켠 사람에게는 움직이지 않고 그대로 보여 준다 */
@media (prefers-reduced-motion: reduce) {
  .cl-home-cat, .cl-home-cat__deco, .cl-home-cat__go { transition: none; }
  .cl-home-cat:hover .cl-home-cat__deco { transform: none; }
  .cl-home-cat:hover .cl-home-cat__go { transform: none; }
}

confirmed.dom:
// 분류 이름으로 아이콘을 정한다 — 랜덤이 아니라 고정이라 같은 분류는 언제나 같은 아이콘
var ICONS = [
  '<path d="M12 7v14"></path><path d="M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3 3 3 3 0 0 0-3-3z"></path>',
  '<circle cx="12" cy="12" r="10"></circle><polygon points="10 8 16 12 10 16 10 8"></polygon>',
  '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87"></path>'
];
doc.querySelectorAll('.cl-home-cat').forEach(function (card) {
  if (card.querySelector('.cl-home-cat__deco')) return;
  var el = card.querySelector('.cl-home-cat__head strong');
  var name = el ? el.textContent.trim() : '';
  var n = 0;
  for (var i = 0; i < name.length; i++) n += name.charCodeAt(i);
  var svg = doc.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'cl-home-cat__deco');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '1.25');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  svg.innerHTML = ICONS[n % ICONS.length];
  card.append(svg);
});

