@media (max-width: 900px) { .cl-scope .cl-pub-btn-pill { height: var(--cl-h-control); padding: 0 10px 0 12px; font-size: var(--cl-fs-ui); } }

/* 학원 머리 프로필 — 동그라미에 딱 맞는 32×32 원. 마우스를 올려도 바뀌지 않는다 */
