.cl-scope .cl-pub-header .cl-ws-account[aria-expanded="true"] { background: transparent; }

/* 머리 안쪽 폭을 본문(.cl-pub-wrap)과 같은 방식으로 — 여백 20 을 1200 바깥에 둔다 */
