}
@media (min-width: 901px) and (max-width: 1240px) {
  .cl-pub-header__inner, .cl-pub-footer__inner { box-sizing: border-box; }
}

/* 알림 종 — 프로필 · 페이지 이동 버튼과 같은 32px 원, 아이콘 20 → 18 */
