var st = doc.querySelector('.cl-ta-stats'); if (!st || st.dataset.na1) return; st.dataset.na1 = '1';
var rows = [].slice.call(st.querySelectorAll('.cl-ta-ranks tbody tr'));
var graded = rows.filter(function (tr) { return !/미채점/.test(tr.children[2].textContent); }).length;
/* 1. 채점한 학생이 없으면 0 대신 — 와 안내 한 줄 */
if (!graded) {
  st.querySelectorAll('.cl-kpi dd').forEach(function (dd) { dd.textContent = '—'; dd.classList.add('is-none'); });
  st.querySelector('.cl-kpi').insertAdjacentHTML('afterend', '<p class="cl-ta-stats__note">아직 채점한 학생이 없어 점수 통계가 비어 있습니다. 채점하면 여기에 바로 반영됩니다.</p>');
}
/* 2. 막대 — 미제출 · 미채점은 회색 */
st.querySelectorAll('.cl-ta-bars li').forEach(function (li) { if (/미제출|미채점/.test(li.firstElementChild.textContent)) li.querySelector('.cl-ta-meter > span').classList.add('is-muted'); });
/* 3. 점수 분포 — '미채점 · 0~20점' 을 두 줄로 나눈다(미채점이 0점대로 읽히지 않게) */
var mix = [].slice.call(st.querySelectorAll('.cl-ta-bars li')).filter(function (li) { return li.firstElementChild.textContent.indexOf('미채점 · 0~20점') === 0; })[0];
if (mix) { var un = rows.length - graded, pct = rows.length ? Math.round(un / rows.length * 100) : 0;
  mix.firstElementChild.textContent = '0~20점'; mix.querySelector('.cl-ta-meter > span').style.width = '0%'; mix.querySelector('.cl-ta-meter > span').classList.remove('is-muted'); mix.lastElementChild.textContent = '0명 (0%)';
  mix.insertAdjacentHTML('afterend', '<li><span>미채점</span><span class="cl-ta-meter"><span class="is-muted" style="width:' + pct + '%"></span></span><span class="cl-num">' + un + '명 (' + pct + '%)</span></li>'); }
/* 4. 순위 — 미채점은 순위 없음(—), 채점한 학생 다음에 */
rows.forEach(function (tr) { if (/미채점/.test(tr.children[2].textContent)) { tr.children[0].textContent = '—'; tr.children[0].classList.add('cl-muted'); tr.children[2].classList.add('cl-muted'); } });
